css:
.search-result-item {
  margin-bottom: 24px;
  padding-bottom: 16px;
  border-bottom: 1px solid #e2e8f0;
}
.search-result-item h3 {
  margin: 0 0 8px 0;
  font-size: 1.25rem;
}
.search-result-item h3 a {
  color: #ea580c;
  text-decoration: none;
  font-weight: 700;
}
.search-result-item h3 a:hover {
  text-decoration: underline;
}
.search-result-item .search-snippet {
  color: #475569;
  font-size: 0.95rem;
  line-height: 1.6;
  margin: 0 0 8px 0;
}
.search-result-item strong.search-highlight {
  background: #fef08a;
  color: #0f172a;
  padding: 2px 4px;
  border-radius: 4px;
  font-weight: bold;
}
.search-result-item .search-date {
  font-size: 0.8rem;
  color: #94a3b8;
}
